const net = require('node:net');
const server = net.createServer((socket) => {         // handler for each accepted handle
  socket.on('data', (chunk) => socket.write(chunk));  // dispatch on readiness, per handle
  socket.on('error', () => socket.destroy());         // per-handler error containment
});
server.listen(8080);                                   // interest registered with the loop's poller
// libuv owns uv_run(); never block it: use fs.promises in handlers, not readFileSync.
